-- Candidate payload statements only, extracted from the unapplied Node v5 draft.
-- The fixed current-format Error is bound as parameter 1. No version/startup hook.
UPDATE ops SET receipt=json_set(receipt,'$.state.error',json(?1)) WHERE CASE WHEN json_valid(receipt) THEN (json_extract(receipt,'$.state.state')='finished' AND json_type(receipt,'$.state.error') IS NOT NULL AND json_type(receipt,'$.state.error')<>'null') ELSE 0 END;
UPDATE ops SET receipt=json_set(receipt,'$.state.result.error',json(?1)) WHERE CASE WHEN json_valid(receipt) THEN (json_extract(receipt,'$.state.state')='finished' AND json_extract(receipt,'$.state.result.kind')='execution' AND json_type(receipt,'$.state.result.error') IS NOT NULL AND json_type(receipt,'$.state.result.error')<>'null') ELSE 0 END;
UPDATE events SET event=json_set(event,'$.body.receipt.state.error',json(?1)) WHERE CASE WHEN json_valid(event) THEN (json_extract(event,'$.body.type')='operation_changed' AND json_extract(event,'$.body.receipt.state.state')='finished' AND json_type(event,'$.body.receipt.state.error') IS NOT NULL AND json_type(event,'$.body.receipt.state.error')<>'null') ELSE 0 END;
UPDATE events SET event=json_set(event,'$.body.receipt.state.result.error',json(?1)) WHERE CASE WHEN json_valid(event) THEN (json_extract(event,'$.body.type')='operation_changed' AND json_extract(event,'$.body.receipt.state.state')='finished' AND json_extract(event,'$.body.receipt.state.result.kind')='execution' AND json_type(event,'$.body.receipt.state.result.error') IS NOT NULL AND json_type(event,'$.body.receipt.state.result.error')<>'null') ELSE 0 END;
UPDATE events SET event=json_set(event,'$.body.completion.error',json(?1)) WHERE CASE WHEN json_valid(event) THEN (json_extract(event,'$.body.type')='attempt_ended' AND json_type(event,'$.body.completion.error') IS NOT NULL AND json_type(event,'$.body.completion.error')<>'null') ELSE 0 END;
